236	    // ---------------------------------------------------------------------
237	    // 投料：放大换算 → 偏差校验 → 称量记录与库存扣减同一事务原子完成
238	    // ---------------------------------------------------------------------
239	
240	    @Transactional
241	    public ServiceResult feed(FeedRequest req) {
242	        Map<String, Object> payload = new LinkedHashMap<>();
243	        payload.put("lotNo", req.lotNo());
244	        List<Map<String, Object>> weighingPayload = new ArrayList<>();
245	        for (WeighingInput w : req.weighings()) {
246	            Map<String, Object> entry = new LinkedHashMap<>();
247	            entry.put("dyeCode", w.dyeCode());
248	            entry.put("actualG", w.actualG());
249	            weighingPayload.add(entry);
250	        }
251	        weighingPayload.sort((a, b) -> String.valueOf(a.get("dyeCode")).compareTo(String.valueOf(b.get("dyeCode"))));
252	        payload.put("weighings", weighingPayload);
253	
254	        return idempotency.execute(req.requestId(), "FEED", payload, () -> {
255	            Map<String, Object> lot = requireLot(req.lotNo());
256	            requireStatus(lot, LotStatus.CREATED);
257	
258	            Long versionRecipeId = recipeId((String) lot.get("recipe_code"),
259	                    ((Number) lot.get("recipe_version")).intValue());
260	            List<Map<String, Object>> items = recipeItems(versionRecipeId);
261	            BigDecimal ratio = (BigDecimal) lot.get("liquor_ratio");
262	            BigDecimal fabricKg = (BigDecimal) lot.get("fabric_weight_kg");
263	
264	            Map<String, BigDecimal> actualByDye = new LinkedHashMap<>();
265	            for (WeighingInput w : req.weighings()) {
266	                if (actualByDye.put(w.dyeCode(), w.actualG()) != null) {
267	                    throw new ApiException(HttpStatus.BAD_REQUEST,
268	                            "染化料 " + w.dyeCode() + " 称量记录重复");
269	                }
270	            }
271	            Set<String> required = new LinkedHashSet<>();
272	            List<Map<String, Object>> computed = new ArrayList<>();
273	            for (Map<String, Object> item : items) {
274	                String dyeCode = (String) item.get("dye_code");
275	                BigDecimal dosage = (BigDecimal) item.get("dosage_gpl");
276	                required.add(dyeCode);
277	                BigDecimal target = dosage.multiply(ratio).multiply(fabricKg).setScale(4, RoundingMode.HALF_UP);
278	                BigDecimal actual = actualByDye.get(dyeCode);
279	                if (actual == null) {
280	                    throw new ApiException(HttpStatus.BAD_REQUEST,
281	                            "缺少染化料 " + dyeCode + " 的实际称量，拒绝投料");
282	                }
283	                BigDecimal deviation = actual.subtract(target)
284	                        .multiply(BigDecimal.valueOf(100))
285	                        .divide(target, DEVIATION_SCALE, RoundingMode.HALF_UP);
286	                if (deviation.abs().compareTo(WEIGH_LIMIT_PCT) > 0) {
287	                    throw new ApiException(HttpStatus.UNPROCESSABLE_ENTITY,
288	                            "染化料 " + dyeCode + " 称量偏差 " + deviation + "% 超过 ±0.5%（恰 0.5% 合法），整单拒绝投料且不扣库存");
289	                }
290	                Map<String, Object> row = new LinkedHashMap<>();
291	                row.put("dyeCode", dyeCode);
292	                row.put("targetG", target);
293	                row.put("actualG", actual);
294	                row.put("deviationPct", deviation);
295	                computed.add(row);
296	            }
297	            if (!actualByDye.keySet().equals(required)) {
298	                Set<String> extra = new LinkedHashSet<>(actualByDye.keySet());
299	                extra.removeAll(required);
300	                throw new ApiException(HttpStatus.BAD_REQUEST,
301	                        "存在配方外染化料称量：" + extra + "，拒绝投料");
302	            }
303	
304	            // 库存预检：任一染化料不足整单回滚，杜绝部分扣减。
305	            for (Map<String, Object> row : computed) {
306	                BigDecimal stock = jdbc.queryForObject("SELECT stock_g FROM dye WHERE code = ?",
307	                        BigDecimal.class, row.get("dyeCode"));
308	                if (stock == null) {
309	                    throw new ApiException(HttpStatus.BAD_REQUEST,
310	                            "染化料 " + row.get("dyeCode") + " 不存在，拒绝投料");
311	                }
312	                if (stock.compareTo((BigDecimal) row.get("actualG")) < 0) {
313	                    throw new ApiException(HttpStatus.CONFLICT,
314	                            "染化料 " + row.get("dyeCode") + " 库存不足，拒绝投料且不扣库存");
315	                }
316	            }
317	
318	            Timestamp now = nowTs();
319	            jdbc.update("INSERT INTO feeding (request_id, lot_id, fed_at) VALUES (?, ?, ?)",
320	                    req.requestId(), lot.get("id"), now);
321	            Long feedingId = jdbc.queryForObject(
322	                    "SELECT id FROM feeding WHERE request_id = ?", Long.class, req.requestId());
323	            for (Map<String, Object> row : computed) {
324	                jdbc.update("INSERT INTO weighing (feeding_id, dye_code, target_g, actual_g, deviation_pct) "
325	                        + "VALUES (?, ?, ?, ?, ?)",
326	                        feedingId, row.get("dyeCode"), row.get("targetG"), row.get("actualG"),
327	                        row.get("deviationPct"));
328	                int deducted = jdbc.update("UPDATE dye SET stock_g = stock_g - ? WHERE code = ? AND stock_g >= ?",
329	                        row.get("actualG"), row.get("dyeCode"), row.get("actualG"));
330	                if (deducted != 1) {
331	                    // 并发扣减防护：与预检构成双保险，失败随事务整体回滚。
332	                    throw new ApiException(HttpStatus.CONFLICT,
333	                            "染化料 " + row.get("dyeCode") + " 并发扣减失败，整单回滚");
334	                }
335	            }
336	            jdbc.update("UPDATE lot SET status = ?, updated_at = ? WHERE id = ?",
337	                    LotStatus.FED.name(), now, lot.get("id"));
338	
339	            Map<String, Object> body = new LinkedHashMap<>();
340	            body.put("requestId", req.requestId());
341	            body.put("lotNo", req.lotNo());
342	            body.put("liquorRatio", ratio);
343	            body.put("fabricWeightKg", fabricKg);
344	            body.put("weighings", computed);
345	            body.put("status", LotStatus.FED.name());
346	            body.put("fedAt", now.toInstant().toString());
347	            return ServiceResult.ok(body);
348	        });
349	    }
