445	        String status = (String) lot.get("status");
446	        boolean replayed = LotStatus.ARCHIVED.name().equals(status);
447	        if (!replayed) {
448	            if (LotStatus.CREATED.name().equals(status) || LotStatus.FED.name().equals(status)
449	                    || LotStatus.REPAIRING.name().equals(status) || LotStatus.MERGED.name().equals(status)) {
450	                throw new ApiException(HttpStatus.CONFLICT,
451	                        "缸次 " + lotNo + " 状态 " + status + "，未出缸判定不得归档");
