466	    @Transactional
467	    public ServiceResult receiveLateColor(String lotNo, LateColorRequest req) {
468	        Map<String, Object> lot = requireLot(lotNo);
469	        Timestamp now = nowTs();
470	        boolean archived = LotStatus.ARCHIVED.name().equals(lot.get("status"));
471	        GeneratedKeyHolder keyHolder = new GeneratedKeyHolder();
472	        jdbc.update(con -> {
473	            PreparedStatement ps = con.prepareStatement(
474	                    "INSERT INTO late_color_event (lot_id, delta_e, note, received_at) VALUES (?, ?, ?, ?)",
475	                    Statement.RETURN_GENERATED_KEYS);
476	            ps.setObject(1, lot.get("id"));
477	            ps.setBigDecimal(2, req.deltaE());
478	            ps.setString(3, req.note());
479	            ps.setTimestamp(4, now);
480	            return ps;
481	        }, keyHolder);
482	        Map<String, Object> body = new LinkedHashMap<>();
483	        body.put("eventId", keyHolder.getKey());
484	        body.put("lotNo", lotNo);
485	        body.put("deltaE", req.deltaE());
486	        body.put("archived", archived);
487	        body.put("recordedOnly", archived);
488	        body.put("message", archived
489	                ? "缸次已判定归档（终态），迟到测色仅登记事件，不改变判定"
490	                : "测色事件已登记");
491	        return ServiceResult.ok(body);
492	    }
