494	    // ---------------------------------------------------------------------
495	    // 查询与复算
496	    // ---------------------------------------------------------------------
497	
498	    @Transactional(readOnly = true)
499	    public ServiceResult getLot(String lotNo) {
500	        return ServiceResult.ok(lotView(lotNo));
501	    }
502	
503	    /**
504	     * 复算配方版本、称量链与缸差台账：重算目标克重/偏差/缸差并与库存与台账逐笔比对。
505	     */
506	    @Transactional(readOnly = true)
507	    public ServiceResult recalculate(String recipeCode) {
508	        List<Map<String, Object>> versions = new ArrayList<>();
509	        List<Map<String, Object>> versionRows = jdbc.queryForList(
510	                "SELECT id, version, liquor_ratio, status FROM recipe WHERE recipe_code = ? ORDER BY version",
511	                recipeCode);
512	        for (Map<String, Object> v : versionRows) {
513	            Map<String, Object> view = new LinkedHashMap<>(v);
514	            view.put("items", recipeItems(((Number) v.get("id")).longValue()));
515	            versions.add(view);
516	        }
517	        if (versions.isEmpty()) {
518	            throw new ApiException(HttpStatus.NOT_FOUND, "配方 " + recipeCode + " 不存在");
519	        }
520	
521	        List<Map<String, Object>> weighingMismatches = new ArrayList<>();
522	        int weighingChecked = 0;
523	        List<Map<String, Object>> lotRows = jdbc.queryForList(
524	                "SELECT * FROM lot WHERE recipe_code = ? ORDER BY id", recipeCode);
525	        for (Map<String, Object> lot : lotRows) {
526	            BigDecimal ratio = (BigDecimal) lot.get("liquor_ratio");
527	            BigDecimal fabric = (BigDecimal) lot.get("fabric_weight_kg");
528	            List<Map<String, Object>> stored = jdbc.queryForList(
529	                    "SELECT dye_code, target_g, actual_g, deviation_pct FROM weighing w "
530	                            + "JOIN feeding f ON f.id = w.feeding_id WHERE f.lot_id = ? ORDER BY w.id",
531	                    lot.get("id"));
532	            for (Map<String, Object> w : stored) {
533	                BigDecimal dosage = jdbc.queryForObject(
534	                        "SELECT dosage_gpl FROM recipe_item ri JOIN recipe r ON r.id = ri.recipe_id "
535	                                + "WHERE r.recipe_code = ? AND r.version = ? AND ri.dye_code = ?",
536	                        BigDecimal.class, recipeCode, lot.get("recipe_version"), w.get("dye_code"));
537	                BigDecimal target = dosage.multiply(ratio).multiply(fabric).setScale(4, RoundingMode.HALF_UP);
538	                BigDecimal deviation = ((BigDecimal) w.get("actual_g")).subtract(target)
539	                        .multiply(BigDecimal.valueOf(100))
540	                        .divide(target, DEVIATION_SCALE, RoundingMode.HALF_UP);
541	                weighingChecked++;
542	                if (target.compareTo((BigDecimal) w.get("target_g")) != 0
543	                        || deviation.compareTo((BigDecimal) w.get("deviation_pct")) != 0) {
544	                    Map<String, Object> mismatch = new LinkedHashMap<>();
545	                    mismatch.put("lotNo", lot.get("lot_no"));
546	                    mismatch.put("dyeCode", w.get("dye_code"));
547	                    mismatch.put("storedTargetG", w.get("target_g"));
548	                    mismatch.put("recomputedTargetG", target);
549	                    mismatch.put("storedDeviationPct", w.get("deviation_pct"));
550	                    mismatch.put("recomputedDeviationPct", deviation);
551	                    weighingMismatches.add(mismatch);
552	                }
553	            }
554	        }
555	
556	        List<Map<String, Object>> judgmentRows = jdbc.queryForList(
557	                "SELECT j.*, l.lot_no AS lot_no FROM lot_judgment j JOIN lot l ON l.id = j.lot_id "
558	                        + "WHERE l.recipe_code = ? ORDER BY j.id", recipeCode);
559	        List<Map<String, Object>> judgmentMismatches = new ArrayList<>();
560	        for (Map<String, Object> j : judgmentRows) {
561	            BigDecimal storedDiff = (BigDecimal) j.get("diff");
562	            Verdict storedVerdict = Verdict.valueOf((String) j.get("verdict"));
563	            BigDecimal recomputedDiff = null;
564	            if (j.get("reference_lot_id") != null) {
565	                Map<String, Object> refRow = jdbc.queryForMap(
566	                        "SELECT delta_e FROM lot_judgment WHERE lot_id = ? ORDER BY id DESC LIMIT 1",
567	                        j.get("reference_lot_id"));
568	                recomputedDiff = ((BigDecimal) j.get("delta_e")).subtract((BigDecimal) refRow.get("delta_e"))
569	                        .abs().setScale(4, RoundingMode.HALF_UP);
570	            }
571	            int round = ((Number) j.get("round")).intValue();
572	            boolean over = recomputedDiff != null && recomputedDiff.compareTo(LOT_DIFF_LIMIT) > 0;
573	            Verdict expectedVerdict;
574	            if (!over) {
575	                expectedVerdict = Verdict.PASS;
576	            } else if (round == 0) {
577	                expectedVerdict = Verdict.REPAIR;
578	            } else {
579	                expectedVerdict = Verdict.DOWNGRADE;
580	            }
581	            boolean diffOk = storedDiff == null ? recomputedDiff == null
582	                    : recomputedDiff != null && storedDiff.compareTo(recomputedDiff) == 0;
583	            if (!diffOk || storedVerdict != expectedVerdict) {
584	                Map<String, Object> mismatch = new LinkedHashMap<>();
585	                mismatch.put("lotNo", j.get("lot_no"));
586	                mismatch.put("storedDiff", storedDiff);
587	                mismatch.put("recomputedDiff", recomputedDiff);
588	                mismatch.put("storedVerdict", storedVerdict.name());
589	                mismatch.put("expectedVerdict", expectedVerdict.name());
590	                judgmentMismatches.add(mismatch);
591	            }
592	        }
593	
594	        Map<String, Object> report = new LinkedHashMap<>();
595	        report.put("recipeCode", recipeCode);
596	        report.put("versions", versions);
597	        report.put("weighingChecked", weighingChecked);
598	        report.put("weighingMismatches", weighingMismatches);
599	        report.put("judgmentChecked", judgmentRows.size());
600	        report.put("judgmentMismatches", judgmentMismatches);
601	        report.put("consistent", weighingMismatches.isEmpty() && judgmentMismatches.isEmpty());
602	        return ServiceResult.ok(report);
603	    }
