609	    private void validateItems(List<RecipeItemInput> items) {
610	        Set<String> codes = new LinkedHashSet<>();
611	        for (RecipeItemInput item : items) {
612	            if (!codes.add(item.dyeCode())) {
613	                throw new ApiException(HttpStatus.BAD_REQUEST, "配方内染化料 " + item.dyeCode() + " 重复");
614	            }
615	            Integer dyeExists = jdbc.query("SELECT 1 FROM dye WHERE code = ?",
616	                    rs -> rs.next() ? 1 : null, item.dyeCode());
617	            if (dyeExists == null) {
618	                throw new ApiException(HttpStatus.BAD_REQUEST, "染化料 " + item.dyeCode() + " 不存在");
619	            }
620	        }
621	    }
