628	    }
629	
630	    private Map<String, Object> latestRecipe(String recipeCode) {
631	        Map<String, Object> row = jdbc.queryForList(
632	                "SELECT id, version, liquor_ratio, status FROM recipe WHERE recipe_code = ? "
633	                        + "ORDER BY version DESC LIMIT 1", recipeCode)
