641	    private Map<String, Object> requirePublishedRecipe(String code, int version) {
642	        List<Map<String, Object>> rows = jdbc.queryForList(
643	                "SELECT id, liquor_ratio, status FROM recipe WHERE recipe_code = ? AND version = ?",
644	                code, version);
645	        if (rows.isEmpty()) {
646	            throw new ApiException(HttpStatus.NOT_FOUND, "配方 " + code + " v" + version + " 不存在");
647	        }
648	        Map<String, Object> row = rows.get(0);
649	        if (!RecipeStatus.PUBLISHED.name().equals(row.get("status"))) {
650	            throw new ApiException(HttpStatus.CONFLICT,
651	                    "配方 " + code + " v" + version + " 未发布冻结，禁止排缸投料");
652	        }
653	        return row;
654	    }
655	
656	    private Long recipeId(String code, int version) {
657	        return jdbc.queryForObject("SELECT id FROM recipe WHERE recipe_code = ? AND version = ?",
658	                Long.class, code, version);
659	    }
660	
661	    private List<Map<String, Object>> recipeItems(Long recipeId) {
662	        return jdbc.queryForList(
663	                "SELECT dye_code, dosage_gpl FROM recipe_item WHERE recipe_id = ? ORDER BY dye_code",
664	                recipeId);
