685	                "SELECT l.* FROM lot l JOIN lot_judgment j ON j.lot_id = l.id "
686	                        + "WHERE l.recipe_code = ? AND l.recipe_version = ? AND l.id <> ? "
687	                        + "GROUP BY l.id ORDER BY MAX(j.id) DESC LIMIT 1",
