17	 */
18	class DyeFlowTest extends BaseIntegrationTest {
19	
20	    // ------------------------------------------------------------------
21	    // 对色：恰 0.8 合格，0.8 以上不放行；requestId 幂等与 409
22	    // ------------------------------------------------------------------
23	
24	    @Test
25	    void colorCheck_exactlyZeroPointEight_passes() {
26	        Map<String, Object> body = postOk("/api/color-checks", Map.of(
27	                "requestId", "cc-1", "sampleId", "S-1", "deltaE", new BigDecimal("0.8")));
28	        assertEquals(true, body.get("passed"));
29	        assertEquals(0, new BigDecimal("0.8").compareTo(bd(body.get("limit"))));
30	    }
31	
32	    @Test
33	    void colorCheck_aboveLimit_rejected_andIdempotentConflictHasNoSideEffect() {
34	        ResponseEntity<Map> first = post("/api/color-checks", Map.of(
35	                "requestId", "cc-2", "sampleId", "S-2", "deltaE", new BigDecimal("0.81")));
36	        assertEquals(200, first.getStatusCode().value());
37	        assertEquals(false, first.getBody().get("passed"));
38	
39	        // 同键同参重放：返回首次结果
40	        ResponseEntity<Map> replay = post("/api/color-checks", Map.of(
41	                "requestId", "cc-2", "sampleId", "S-2", "deltaE", new BigDecimal("0.81")));
42	        assertEquals(200, replay.getStatusCode().value());
43	        assertEquals("true", replay.getHeaders().getFirst("X-Idempotent-Replayed"));
44	        assertEquals(Long.valueOf(1), jdbc.queryForObject(
45	                "SELECT COUNT(*) FROM color_check WHERE request_id = 'cc-2'", Long.class));
46	
47	        // 同键异参：409，且不新增对色记录
