package com.example.starter;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.math.BigDecimal;
import java.time.Clock;
import java.time.Instant;
import java.time.ZoneId;
import java.util.List;
import java.util.Map;
import java.util.concurrent.atomic.AtomicReference;

import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;
import org.springframework.http.ResponseEntity;
import org.springframework.test.context.bean.override.mockito.MockitoBean;

/**
 * 批次有效期边界（可控时钟）：now&lt;截止有效，恰在截止失效；审批与投料两个时点都校验。
 */
class DyeCompensationExpiryTest extends BaseIntegrationTest {

    private static final Instant T0 = Instant.parse("2026-09-28T08:00:00Z");

    @MockitoBean
    private Clock clock;

    private final AtomicReference<Instant> nowRef = new AtomicReference<>(T0);

    @BeforeEach
    void stubClock() {
        nowRef.set(T0);
        Mockito.lenient().when(clock.instant()).thenAnswer(inv -> nowRef.get());
        Mockito.lenient().when(clock.getZone()).thenReturn(ZoneId.of("Asia/Shanghai"));
    }

    @Test
    void approval_exactlyAtDeadline_rejected_oneSecondBefore_allowed() {
        String deadline = T0.plusSeconds(3600).toString();
        postOk("/api/dye-lots", Map.of(
                "requestId", "ex-dl-1", "lotCode", "LOT-TR", "dyeCode", "D-RED",
                "potency", new BigDecimal("2.0"), "availableG", new BigDecimal("2000"),
                "validUntil", deadline));
        registerDyeLot("ex-dl-2", "LOT-TY", "D-YELLOW", "1.5", "2000");
        registerDyeLot("ex-dl-3", "LOT-TB", "D-BLUE", "1.0", "2000");
        schedule("ex-sc", "LT", "VT", "R-BASE", 1, "50");

        // 恰在截止：失效，整单拒绝
        nowRef.set(T0.plusSeconds(3600));
        ResponseEntity<Map> atDeadline = post("/api/compensations", Map.of(
                "requestId", "ex-ap-1", "lotNo", "LT",
                "items", List.of(
                        Map.of("dyeCode", "D-RED", "lotCode", "LOT-TR", "potencyVersion", 1),
                        Map.of("dyeCode", "D-YELLOW", "lotCode", "LOT-TY", "potencyVersion", 1),
                        Map.of("dyeCode", "D-BLUE", "lotCode", "LOT-TB", "potencyVersion", 1))));
        assertEquals(422, atDeadline.getStatusCode().value());
        assertEquals(Long.valueOf(0), jdbc.queryForObject(
                "SELECT COUNT(*) FROM comp_approval WHERE lot_no='LT'", Long.class));

        // 截止前一秒：有效，批准成功（失败不占键，同键可重试）
        nowRef.set(T0.plusSeconds(3599));
        ResponseEntity<Map> beforeDeadline = post("/api/compensations", Map.of(
                "requestId", "ex-ap-1", "lotNo", "LT",
                "items", List.of(
                        Map.of("dyeCode", "D-RED", "lotCode", "LOT-TR", "potencyVersion", 1),
                        Map.of("dyeCode", "D-YELLOW", "lotCode", "LOT-TY", "potencyVersion", 1),
                        Map.of("dyeCode", "D-BLUE", "lotCode", "LOT-TB", "potencyVersion", 1))));
        assertEquals(201, beforeDeadline.getStatusCode().value());
    }

    @Test
    void feed_atOrAfterDeadline_rejected_batchRemainingUntouched() {
        String deadline = T0.plusSeconds(3600).toString();
        postOk("/api/dye-lots", Map.of(
                "requestId", "ex2-dl-1", "lotCode", "LOT-FR", "dyeCode", "D-RED",
                "potency", new BigDecimal("2.0"), "availableG", new BigDecimal("2000"),
                "validUntil", deadline));
        registerDyeLot("ex2-dl-2", "LOT-FY", "D-YELLOW", "1.5", "2000");
        registerDyeLot("ex2-dl-3", "LOT-FB", "D-BLUE", "1.0", "2000");
        schedule("ex2-sc", "LF2", "VF2", "R-BASE", 1, "50");
        approve("ex2-ap", "LF2", List.of(
                List.of("D-RED", "LOT-FR", 1),
                List.of("D-YELLOW", "LOT-FY", 1),
                List.of("D-BLUE", "LOT-FB", 1)));

        // 审批后到投料前到达截止时刻：投料拒绝，批次余量不动
        nowRef.set(T0.plusSeconds(3600));
        ResponseEntity<Map> feed = post("/api/feedings", Map.of(
                "requestId", "ex2-feed", "lotNo", "LF2",
                "weighings", List.of(
                        Map.of("dyeCode", "D-RED", "actualG", new BigDecimal("500.000")),
                        Map.of("dyeCode", "D-YELLOW", "actualG", new BigDecimal("500.000")),
                        Map.of("dyeCode", "D-BLUE", "actualG", new BigDecimal("250.000")))));
        assertEquals(422, feed.getStatusCode().value());
        assertEquals(0, new BigDecimal("2000.000").compareTo(batchAvailable("LOT-FR")));
        assertEquals("CREATED", jdbc.queryForObject(
                "SELECT status FROM lot WHERE lot_no='LF2'", String.class));
    }
}

package com.example.starter;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNotEquals;

import java.math.BigDecimal;
import java.time.Clock;
import java.time.Instant;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

import org.junit.jupiter.api.Test;

import com.example.starter.service.IdempotencyService;
import com.fasterxml.jackson.databind.ObjectMapper;

/**
 * 幂等指纹结构化无歧义：合法文本含分隔符也须区分；版本、集合与精确时刻都参与指纹。
 */
class FingerprintTest {

    private final IdempotencyService idempotency =
            new IdempotencyService(null, new ObjectMapper(), Clock.systemUTC());

    private String fp(String operation, String requestId, Map<String, Object> payload) {
        return idempotency.fingerprint(operation, requestId, payload);
    }

    @Test
    void separatorInsideText_stillDistinguishable() {
        // 朴素拼接 "A|B|C" 会撞车；结构化指纹须区分分隔符落在哪个字段
        Map<String, Object> p1 = new LinkedHashMap<>();
        p1.put("dyeCode", "A|B");
        p1.put("lotCode", "C");
        Map<String, Object> p2 = new LinkedHashMap<>();
        p2.put("dyeCode", "A");
        p2.put("lotCode", "B|C");
        assertNotEquals(fp("OP", "r1", p1), fp("OP", "r1", p2));
    }

    @Test
    void sameParams_sameFingerprint_regardlessOfKeyOrderAndNumberScale() {
        Map<String, Object> p1 = new LinkedHashMap<>();
        p1.put("lotNo", "L1");
        p1.put("potency", new BigDecimal("1.0"));
        Map<String, Object> p2 = new LinkedHashMap<>();
        p2.put("potency", new BigDecimal("1.00"));
        p2.put("lotNo", "L1");
        assertEquals(fp("OP", "r1", p1), fp("OP", "r1", p2));
    }

    @Test
    void versionCollectionAndExactMoment_allCovered() {
        Map<String, Object> item = new LinkedHashMap<>();
        item.put("dyeCode", "D-RED");
        item.put("lotCode", "LOT-1");
        item.put("potencyVersion", 1);
        Map<String, Object> base = new LinkedHashMap<>();
        base.put("lotNo", "L1");
        base.put("expectedVersion", 1);
        base.put("validUntil", Instant.parse("2026-12-31T16:00:00Z"));
        base.put("items", List.of(item));

        Map<String, Object> same = new LinkedHashMap<>(base);
        assertEquals(fp("OP", "r1", base), fp("OP", "r1", same));

        Map<String, Object> otherVersion = new LinkedHashMap<>(base);
        otherVersion.put("expectedVersion", 2);
        assertNotEquals(fp("OP", "r1", base), fp("OP", "r1", otherVersion));

        Map<String, Object> otherMoment = new LinkedHashMap<>(base);
        otherMoment.put("validUntil", Instant.parse("2026-12-31T16:00:01Z"));
        assertNotEquals(fp("OP", "r1", base), fp("OP", "r1", otherMoment));

        Map<String, Object> otherItem = new LinkedHashMap<>();
        otherItem.put("dyeCode", "D-RED");
        otherItem.put("lotCode", "LOT-1");
        otherItem.put("potencyVersion", 2);
        Map<String, Object> otherCollection = new LinkedHashMap<>(base);
        otherCollection.put("items", List.of(otherItem));
        assertNotEquals(fp("OP", "r1", base), fp("OP", "r1", otherCollection));

        // 操作类型与 requestId 同样参与指纹
        assertNotEquals(fp("OP", "r1", base), fp("OP", "r2", base));
        assertNotEquals(fp("OP", "r1", base), fp("OTHER", "r1", base));
    }
}

